```python
from collections import defaultdict

def group_and_sort(records):
    groups = defaultdict(list)

    for r in records:
        groups[r["category"]].append(r)

    for category in groups:
        groups[category].sort(key=lambda x: x["score"])

    return dict(groups)
```

Example:
```python
records = [
    {"category": "A", "name": "x", "score": 30},
    {"category": "B", "name": "y", "score": 20},
    {"category": "A", "name": "z", "score": 10},
]

result = group_and_sort(records)
print(result)
```

